<template>
 <section class="auw" :class="['auw-'+node.type,node.type==='notice'?'auw-'+(node.tone||'info'):'']">
  <header class="auw-head"><span class="auw-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><template v-if="node.type==='steps'"><path d="M5 6h14M5 12h14M5 18h14"/><circle cx="5" cy="6" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="18" r="2"/></template><template v-else-if="node.type==='checklist'"><rect x="5" y="4" width="14" height="17" rx="3"/><path d="M9 4V2h6v2M8 10l2 2 4-4M8 17h8"/></template><template v-else-if="node.type==='timeline'"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></template><template v-else-if="node.type==='faq'"><path d="M7 19l-3 2V5a2 2 0 012-2h12a2 2 0 012 2v12a2 2 0 01-2 2H7zM9 8a3 3 0 015 1c0 2-2 2-2 4M12 16h.01"/></template><template v-else><circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/></template></svg></span><div><span class="auw-kicker">{{ labels[node.type] }}</span><h4>{{ node.title }}</h4></div><span v-if="interactive" class="auw-count" aria-live="polite">{{ checked.size }} / {{ items.length }}</span><span v-else-if="node.type==='faq'" class="auw-count">{{ node.items.length }} 个问题</span></header>
  <p v-if="'note' in node&&node.note" class="auw-note">{{ node.note }}</p>
  <template v-if="interactive">
   <div class="auw-progress" role="progressbar" :aria-label="node.type==='steps'?'流程标记进度':'清单准备进度'" :aria-valuemin="0" :aria-valuemax="items.length" :aria-valuenow="checked.size"><span :style="{width:progress+'%'}"/></div>
   <ol class="auw-list" :class="{'is-flow':node.type==='steps'}"><li v-for="(item,i) in items" :key="i" :class="{'is-checked':checked.has(i),'is-next':node.type==='steps'&&i===next}">
    <label class="auw-item-head"><input type="checkbox" :checked="checked.has(i)" :disabled="disabled" :aria-label="node.type==='steps'?'标记第'+(i+1)+'步完成':'备齐'+item.title" @change="toggle(i)"/><span v-if="node.type==='steps'" class="auw-order" aria-hidden="true">{{ checked.has(i)?'✓':i+1 }}</span><span class="auw-item-title">{{ item.title }}</span><span v-if="'required' in item&&item.required===false" class="auw-optional">可选</span></label>
    <p v-if="item.desc&&item.desc.length<=220" class="auw-desc">{{ item.desc }}</p><template v-else-if="item.desc"><p class="auw-desc">{{ item.desc.slice(0,220) }}…</p><details class="auw-detail"><summary>查看完整说明</summary><MarkdownView class="auw-rich" :content="item.desc"/></details></template>
   </li></ol>
   <footer class="auw-footer"><span>{{ node.type==='steps'?'勾选仅记录个人操作进度，不代表已提交或审批。':'勾选仅记录本浏览器的准备状态，不代表材料已提交。' }}</span><button type="button" :disabled="disabled||!checked.size" @click="reset">清空标记</button></footer>
  </template>
  <ol v-else-if="node.type==='timeline'" class="auw-timeline"><li v-for="(item,i) in node.items" :key="i"><span class="auw-time">{{ item.date }}</span><div><strong>{{ item.title }}</strong><p v-if="item.desc">{{ item.desc }}</p></div></li></ol>
  <div v-else-if="node.type==='faq'" class="auw-faq"><details v-for="(item,i) in node.items" :key="i"><summary>{{ item.question }}<span aria-hidden="true">＋</span></summary><MarkdownView class="auw-rich" :content="item.answer"/></details></div>
  <MarkdownView v-else-if="node.type==='notice'" class="auw-body auw-rich" :content="node.body"/>
 </section>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {UiSteps,UiChecklist,UiTimeline,UiNotice,UiFaq} from '@/utils/agent-ui'
import {workflowProgressKey,loadWorkflowProgress,saveWorkflowProgress} from '@/utils/workflow-progress'
import MarkdownView from '../MarkdownView.vue'
const props=defineProps<{node:UiSteps|UiChecklist|UiTimeline|UiNotice|UiFaq;disabled?:boolean;stateKey?:string}>()
const labels={steps:'按顺序办理',checklist:'逐项准备',timeline:'时间安排',notice:'特别提醒',faq:'常见问题'}
const interactive=computed(()=>props.node.type==='steps'||props.node.type==='checklist')
const items=computed(()=>props.node.type==='steps'?props.node.steps:props.node.type==='checklist'?props.node.items:[])
const key=computed(()=>workflowProgressKey(props.stateKey,props.node.id,items.value)),checked=ref(new Set<number>())
let storage:Storage|undefined;try{storage=window.localStorage}catch{/* Progress remains available in memory. */}
watch(()=>[key.value,JSON.stringify(items.value)],()=>{checked.value=new Set(loadWorkflowProgress(storage,key.value,items.value.length))},{immediate:true})
const progress=computed(()=>items.value.length?Math.round(100*checked.value.size/items.value.length):0),next=computed(()=>items.value.findIndex((_,i)=>!checked.value.has(i)))
function toggle(i:number){if(props.disabled)return;const marks=new Set(checked.value);marks.has(i)?marks.delete(i):marks.add(i);checked.value=marks;saveWorkflowProgress(storage,key.value,[...marks])}
function reset(){if(props.disabled)return;checked.value=new Set();saveWorkflowProgress(storage,key.value,[])}
</script>
<style scoped>
.auw{border:1px solid var(--aui-line);border-radius:18px;background:var(--aui-bg);padding:22px;overflow:hidden;min-width:0}.auw-head{display:flex;gap:12px;align-items:center;margin-bottom:18px}.auw-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;color:var(--aui-accent);background:var(--aui-accent-soft);flex-shrink:0}.auw-icon svg{width:22px;height:22px}.auw-head>div{min-width:0;flex:1}.auw h4{font-size:17px;line-height:1.5}.auw-kicker{font-size:10px;color:var(--aui-muted);letter-spacing:.1em}.auw-count{color:var(--aui-accent);font:600 12px/1.5 inherit;font-variant-numeric:tabular-nums;white-space:nowrap;padding:5px 9px;background:var(--aui-accent-soft);border-radius:8px}.auw-note{color:var(--aui-muted);font-size:13px;white-space:pre-wrap;margin-bottom:16px!important}.auw-progress{height:4px;border-radius:4px;overflow:hidden;background:var(--aui-soft);margin-bottom:18px}.auw-progress span{display:block;height:100%;background:var(--aui-accent);transition:width .2s}.auw-list{list-style:none;margin:0;padding:0}.auw-list li{position:relative;padding:14px 0;border-bottom:1px solid var(--aui-line)}.auw-list li:last-child{border-bottom:0}.auw-item-head{display:flex;align-items:flex-start;gap:12px;cursor:pointer;min-height:28px}.auw-item-head input{width:18px;height:18px;flex-shrink:0;accent-color:var(--aui-accent);margin:4px 0}.auw-item-head:has(input:disabled){cursor:default}.auw-item-title{font-size:14px;font-weight:600;line-height:1.8;flex:1}.auw-order{width:28px;height:28px;display:grid;place-items:center;flex-shrink:0;border:1px solid var(--aui-line);border-radius:50%;font-size:12px;color:var(--aui-muted);background:var(--aui-bg);position:relative;z-index:1}.is-next .auw-order,.is-checked .auw-order{border-color:var(--aui-accent);color:var(--aui-accent);background:var(--aui-accent-soft)}.is-flow li:not(:last-child)::after{content:'';position:absolute;left:43px;top:42px;bottom:-14px;width:1px;background:var(--aui-line)}.auw-desc,.auw-detail{margin:5px 0 0 30px!important;color:var(--aui-muted);font-size:13px;line-height:1.9;white-space:pre-wrap}.is-flow .auw-desc,.is-flow .auw-detail{margin-left:70px!important}.auw-detail summary{cursor:pointer;color:var(--aui-accent);font-size:12px}.auw-detail p{margin-top:8px!important}.is-checked .auw-item-title{color:var(--aui-muted)}.auw-checklist .is-checked .auw-item-title{text-decoration:line-through}.auw-optional{font-size:10px;color:var(--aui-muted);background:var(--aui-soft);padding:2px 6px;border-radius:5px}.auw-footer{display:flex;justify-content:space-between;gap:14px;align-items:center;border-top:1px solid var(--aui-line);padding-top:14px;margin-top:12px;font-size:11px;color:var(--aui-muted)}.auw-footer button{background:transparent;color:var(--aui-accent);border:0;padding:6px 0;white-space:nowrap;font-size:11px}.auw-footer button:disabled{color:var(--aui-muted)}.auw-timeline{margin:0;padding:0;list-style:none}.auw-timeline li{display:grid;grid-template-columns:minmax(70px,110px) minmax(0,1fr);gap:18px;position:relative;margin-left:4px;padding:0 0 24px 20px;border-left:1px solid var(--aui-line)}.auw-timeline li:last-child{padding-bottom:0;border-left-color:transparent}.auw-timeline li::before{content:'';position:absolute;left:-4px;top:7px;width:7px;height:7px;border-radius:50%;background:var(--aui-accent);box-shadow:0 0 0 4px var(--aui-bg)}.auw-time{color:var(--aui-accent);font-size:12px;white-space:pre-wrap;font-variant-numeric:tabular-nums}.auw-timeline strong{font-size:14px;font-weight:600}.auw-timeline p{font-size:13px;white-space:pre-wrap;color:var(--aui-muted);margin-top:6px!important;line-height:1.9}.auw-body{white-space:pre-wrap;line-height:1.9;font-size:14px}.auw-notice{border-left:3px solid var(--aui-accent);background:var(--aui-soft)}.auw-warning{border-left-color:var(--el-color-warning)}.auw-warning .auw-icon{color:var(--el-color-warning);background:var(--el-color-warning-light-9)}.auw-success{border-left-color:var(--el-color-success)}.auw-success .auw-icon{color:var(--el-color-success);background:var(--el-color-success-light-9)}.auw-faq details{border-top:1px solid var(--aui-line)}.auw-faq summary{display:flex;gap:16px;justify-content:space-between;align-items:center;padding:15px 0;cursor:pointer;font-size:14px;font-weight:550;list-style:none}.auw-faq summary::-webkit-details-marker{display:none}.auw-faq summary span{color:var(--aui-accent);font-size:18px;flex-shrink:0}.auw-faq details[open] summary span{transform:rotate(45deg)}.auw-faq p{white-space:pre-wrap;line-height:1.9;color:var(--aui-muted);font-size:13px;padding-bottom:16px}.auw :is(summary,button,input):focus-visible{outline:3px solid var(--nx-focus-ring);outline-offset:4px}
.auw-rich{font-size:13px;color:var(--aui-muted);line-height:1.9}.auw-rich :deep(p){margin:0 0 10px}.auw-rich :deep(p:last-child){margin-bottom:0}.auw-rich :deep(ul),.auw-rich :deep(ol){padding-left:20px}.auw-rich :deep(a){color:var(--aui-accent)}.auw-faq .auw-rich{padding-bottom:16px}
@media(max-width:600px){.auw{padding:17px}.auw h4{font-size:16px}.auw-timeline li{grid-template-columns:minmax(65px,85px) minmax(0,1fr);gap:12px}.auw-count{font-size:11px}.auw-footer{align-items:flex-start}.auw-footer>span{max-width:80%}.auw-head{gap:10px}}
@media(prefers-reduced-motion:reduce){.auw-progress span{transition:none}}
</style>
